<script lang="ts">import type { ReviewDocument } from './types'; import { percent } from './types'; let { forge }: { forge?: ReviewDocument['forge'] } = $props();</script><aside class="forge"><h3>Game evidence</h3>{#if forge?.status === 'available'}<p>{forge.games} games · win rate {forge.win_rate == null ? 'unavailable' : percent(forge.win_rate)}</p>{#each forge.notes ?? [] as note}<p>{note}</p>{/each}{:else}<p>Unavailable — {forge?.reason ?? 'Forge game logs were not requested.'}</p>{/if}</aside>
